#include <fstream>
#include <iostream>

int main() {
    {
        std::ofstream out("temperatures.txt");
        if (!out) { std::cerr << "Kan inte skriva\n"; return 1; }
        for (int i = 0; i < 5; i++) {
            float t;
            std::cout << "Temperatur " << i + 1 << ": ";
            std::cin >> t;
            out << t << "\n";
        }
    }   // out stängs här

    std::ifstream in("temperatures.txt");
    if (!in) { std::cerr << "Kan inte läsa\n"; return 1; }
    float t, sum = 0;
    int n = 0;
    while (in >> t) { sum += t; n++; }
    if (n > 0) std::cout << "Medel: " << sum / n << "\n";
}
